  ('Red Leopard Skin Jasper Cube Bracelet', 'red-leopard-skin-jasper-bracelet-iii', 'Cut into clean cubes, Red Leopard Skin Jasper shows its natural spotted pattern in warm reds, rose, cream and earthy browns, so no two beads look quite alike. Small dark spacers sit between the stones, and a single silver-tone cube with an engraved mark adds a quiet point of light to the strand. Designed in Hong Kong with materials sourced from around the world, it is a considered piece for everyday wear, and arrives gift-ready.', 'JQJ-RLSJ-III', 599.99, null, (select id from public.categories where slug = 'bracelets'), array['/products/red-leopard-jasper-bracelet.webp']::text[], true, 12, 5, '{}'::text[], 'Red Leopard Skin Jasper', array['Designed in Hong Kong', 'Natural stones selected for colour and character']::text[], '{"Stone":"Red Leopard Skin Jasper","Bead Shape":"Cube","Accent":"One silver-tone cube with an engraved mark","Spacers":"Small dark spacers","Care":"Keep dry. Store separately. Wipe with a soft cloth.","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Raw Brown Tourmaline Bracelet I (8-10mm)', 'raw-brown-tourmaline-bracelet-i', 'Raw brown tourmaline nuggets are left close to their natural form, highlighting each stone''s individual texture. Designed for everyday wear with artisanal character.', 'JQJ-TOURM-I', 368.99, null, (select id from public.categories where slug = 'bracelets'), array['/products/brown-tourmaline-bracelet.webp']::text[], true, 8, 5, array['new']::text[], 'Brown Tourmaline', array['Tailored for your preferred fit', 'Natural gemstones selected for color and character', 'Designed in Hong Kong']::text[], '{"Color":"Brown","Bead Size":"8-10mm","Bead Shape":"Irregular","Stone":"Brown Tourmaline","Clasp":"Sterling Silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Sodalite Bracelet VIII (4mm)', 'sodalite-bracelet-viii', 'Deep blue sodalite with subtle white veining is finished with precision silver accents for a clean, understated look rooted in quiet confidence.', 'JQJ-SOD-VIII', 549.99, null, (select id from public.categories where slug = 'bracelets'), array['/products/sodalite-bracelet.webp']::text[], true, 15, 5, '{}'::text[], 'Sodalite', array['Tailored for your preferred fit', 'Natural gemstones selected for color and character', 'Designed in Hong Kong']::text[], '{"Color":"Blue","Bead Size":"4mm","Bead Shape":"Round","Stone":"Sodalite","Clasp":"Sterling Silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Amethyst Bracelet XV (5mm)', 'amethyst-bracelet-xv', 'Faceted amethyst beads in graduated violet tones create an elegant rhythm. A versatile piece that moves effortlessly from daytime polish to evening refinement.', 'JQJ-AMETH-XV', 330.99, null, (select id from public.categories where slug = 'bracelets'), array['/products/amethyst-bracelet.webp']::text[], true, 20, 5, array['new', 'limited']::text[], 'Amethyst', array['Tailored for your preferred fit', 'Natural gemstones selected for color and character', 'Designed in Hong Kong']::text[], '{"Color":"Purple","Bead Size":"5mm","Bead Shape":"Round","Stone":"Amethyst","Clasp":"Sterling Silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Silver Bracelet IV (4mm)', 'silver-bracelet-iv', 'A modern essential with polished silver-tone beads and a minimalist silhouette. Designed to layer well and complement a wide range of looks.', 'JQJ-SIL-IV', 449.99, 499.99, (select id from public.categories where slug = 'bracelets'), array['/products/silver-bracelet.webp']::text[], true, 9, 5, array['restocked', 'sale']::text[], 'Hematite', array['Tailored for your preferred fit', 'Natural gemstones selected for color and character', 'Designed in Hong Kong']::text[], '{"Color":"Silver","Bead Size":"4mm","Bead Shape":"Round","Stone":"Hematite","Clasp":"Sterling Silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Labradorite Bracelet V (8mm)', 'labradorite-bracelet-v', 'Iridescent labradorite reveals blue-gold flashes as it catches the light. A quiet statement piece with depth, movement, and refined presence.', 'JQJ-LABR-V', 519.99, null, (select id from public.categories where slug = 'bracelets'), array['/products/labradorite-bracelet.webp']::text[], true, 6, 5, array['limited']::text[], 'Labradorite', array['Tailored for your preferred fit', 'Natural gemstones selected for color and character', 'Designed in Hong Kong']::text[], '{"Color":"Gray","Bead Size":"8mm","Bead Shape":"Round","Stone":"Labradorite","Clasp":"Sterling Silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Blue Lace Agate Silver Pendant', 'blue-lace-agate-silver-pendant', 'A slender flat bar of blue lace agate, capped at each end in sterling silver, hangs from a diamond-shaped bail on a sterling silver curb chain. Available in 45 cm or 55 cm.', 'JQJ-BLAPEN', 249.99, null, (select id from public.categories where slug = 'necklaces'), array['/products/blue-lace-agate-pendant.webp']::text[], true, 18, 5, array['new']::text[], 'Blue Lace Agate', array['Designed in Hong Kong', 'Sterling silver']::text[], '{"Chain Length":"45 cm or 55 cm","Stone":"Blue Lace Agate","Metal":"Sterling silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Labradorite Silver Pendant', 'labradorite-silver-pendant', 'A slender bar of labradorite with angled ends and a soft blue sheen, capped top and bottom in sterling silver, on a diamond-shaped bail and sterling silver curb chain. 55 cm.', 'JQJ-LABPEN', 279.99, null, (select id from public.categories where slug = 'necklaces'), array['/products/labradorite-pendant.webp']::text[], true, 11, 5, array['restocked']::text[], 'Labradorite', array['Designed in Hong Kong', 'Sterling silver']::text[], '{"Chain Length":"55 cm","Stone":"Labradorite","Metal":"Sterling silver","Origin":"Designed in Hong Kong"}'::jsonb),
  ('Pearl - Silver Necklace V (7mm)', 'pearl-silver-necklace-v', '7 mm freshwater pearls with silver-tone hematite spacers. 45 cm.', 'JQJ-PEARL-V', 980, null, (select id from public.categories where slug = 'necklaces'), array['/products/pearl-silver-necklace.webp']::text[], true, 5, 5, array['limited']::text[], 'Freshwater Pearl', array['Designed in Hong Kong', 'Sterling silver']::text[], '{"Bead Size":"7 mm","Chain Length":"45 cm","Stone":"Freshwater Pearl","Spacers":"Hematite","Origin":"Designed in Hong Kong"}'::jsonb)
